// 当日分の集計（Phase1: views/clicks未取得のため投稿実績中心）
const jst = new Date(Date.now() + 9 * 3600000);
const today = jst.toISOString().slice(0, 10);
let posts = [];
try { posts = $('Read posts').all().map(i => i.json).filter(r => r && r.thread_id); } catch (e) {}
let queue = [];
try { queue = $('Read post_queue').all().map(i => i.json).filter(r => r && r.itemCode); } catch (e) {}
const todayPosts = posts.filter(r => String(r.posted_at || '').slice(0, 10) === today);
const todayQueue = queue.filter(r => String(r.date) === today);
const postedSlots = [...new Set(todayPosts.map(r => Number(r.slot)))].sort();
const skippedSlots = [1, 2, 3].filter(s => !postedSlots.includes(s));
const explorationCount = todayQueue.filter(r => r.is_exploration === true || String(r.is_exploration).toLowerCase() === 'true').length;
const readyLeft = todayQueue.filter(r => String(r.status) === 'ready').length;
return [{ json: {
  date: today,
  posts_count: todayPosts.length,
  queue_count: todayQueue.length,
  posted_slots: postedSlots.join(','),
  skipped_slots: skippedSlots.join(','),
  exploration_count: explorationCount,
  ready_left: readyLeft
} }];

// 異常検知 + 日報Markdown組み立て
const j = $input.first().json;
const alerts = [];
if (j.queue_count === 0) alerts.push('🔴 キュー生成失敗（当日post_queue 0件。705Aの実行ログとコンプラゲート全落ちを確認）');
if (j.posts_count === 0) alerts.push('🔴 投稿0本');
if (j.queue_count > 0 && j.posts_count === 0) alerts.push('🔴 キューはあるが投稿されず（705Bの実行ログを確認）');
const lines = [
  `*DEV_RIO_705 日報 — ${j.date}*`,
  '',
  `- 投稿数: ${j.posts_count}/3（投稿済み枠: ${j.posted_slots || 'なし'}）`,
  `- スキップ枠: ${j.skipped_slots || 'なし'}`,
  `- 当日キュー: ${j.queue_count}件（未投稿ready残: ${j.ready_left}件）`,
  `- 探索枠(ε): ${j.exploration_count}件`
];
if (alerts.length) {
  lines.push('', ...alerts);
} else {
  lines.push('', '✅ 異常なし');
}
lines.push('', '※Phase1のため views/clicks は未計測。投稿実績のみの集計。');
return [{ json: {
  date: j.date,
  posts_count: j.posts_count,
  queue_count: j.queue_count,
  posted_slots: j.posted_slots,
  skipped_slots: j.skipped_slots,
  exploration_count: j.exploration_count,
  alerts: alerts.join(' / '),
  report: lines.join('\n')
} }];
